window.BOOK={"key":"munfarija","app":"mutoon-munfarija","lsk":"mutoon_munfarija_v1","prefix":"mu_","title":"المنفرجة","sub":"التزكية والرقائق · ابن النحوي التوزري (ت ٥١٣هـ) · ٤٠ بيتًا","poems":[{"id":"munfarija","title":"المنفرجة","nazim":"أبو الفضل يوسف بن محمد بن يوسف التوزري، المعروف بابن النحوي","death":"ت ٥١٣هـ","meter":"الخبب (المتدارك)","source":"جامع الكتب الإسلامية: القصيدة المنفرجة لابن النحوي (متن شرح زكريا الأنصاري، مشكول)","srcUrl":"https://ketabonline.com/ar/books/102506","note":"المنفرجة «اشتدي أزمة تنفرجي» (٤٠ بيتًا) من المتن المشكول المجرّد من شرح زكريا الأنصاري «الأضواء البهجة»، قوبلت كلمةً كلمةً بسكربت بمتن الشرح في طبعة «المنفرجتان» المشكولة وبنص طبقات الشافعية الكبرى للسبكي (٣٩ بيتًا)، واعتُمد ما اتفق عليه الأكثر وما يستقيم به الوزن. صُحّحت أخطاء الطبع والشكل وأُكمل الناقص، وفُحص وزن كل شطر، والتفصيل في تقرير المصادر.","verses":[["اشْتَدِّي أَزْمَةُ تَنْفَرِجِي","قَدْ آذَنَ لَيْلُكِ بِالْبَلَجِ"],["وَظَلَامُ اللَّيْلِ لَهُ سُرُجٌ","حَتَّى يَغْشَاهُ أَبُو السُّرُجِ"],["وَسَحَابُ الْخَيْرِ لَهَا مَطَرٌ","فَإِذَا جَاءَ الْإِبَّانُ تَجِي"],["وَفَوَائِدُ مَوْلَانَا جُمَلٌ","لِسُرُوحِ الْأَنْفُسِ وَالْمُهَجِ"],["وَلَهَا أَرَجٌ مُحْيٍ أَبَدًا","فَاقْصِدْ مَحْيَا ذَاكَ الْأَرَجِ"],["فَلَرُبَّتَمَا فَاضَ الْمَحْيَا","بِبُحُورِ الْمَوْجِ مِنَ اللُّجَجِ"],["وَالْخَلْقُ جَمِيعًا فِي يَدِهِ","فَذَوُو سَعَةٍ وَذَوُو حَرَجِ"],["وَنُزُولُهُمُ وَطُلُوعُهُمُ","فَعَلَى دَرَكٍ وَعَلَى دَرَجِ"],["وَمَعَايِشُهُمْ وَعَوَاقِبُهُمْ","لَيْسَتْ فِي الْمَشْيِ عَلَى عِوَجِ"],["حِكَمٌ نُسِجَتْ بِيَدٍ حَكَمَتْ","ثُمَّ انْتَسَجَتْ بِالْمُنْتَسِجِ"],["فَإِذَا اقْتَصَدَتْ ثُمَّ انْعَرَجَتْ","فَبِمُقْتَصِدٍ وَبِمُنْعَرِجِ"],["شَهِدَتْ بِعَجَائِبِهَا حُجَجٌ","قَامَتْ بِالْأَمْرِ عَلَى الْحِجَجِ"],["وَرِضًا بِقَضَاءِ اللَّهِ حَجًا","فَعَلَى مَرْكُوزَتِهِ فَعُجِ"],["وَإِذَا انْفَتَحَتْ أَبْوَابُ هُدًى","فَاعْجَلْ لِخَزَائِنِهَا وَلِجِ"],["وَإِذَا حَاوَلْتَ نِهَايَتَهَا","فَاحْذَرْ إِذْ ذَاكَ مِنَ الْعَرَجِ"],["لِتَكُونَ مِنَ السُّبَّاقِ إِذَا","مَا جِئْتَ إِلَى تِلْكَ الْفُرَجِ"],["فَهُنَاكَ الْعَيْشُ وَبَهْجَتُهُ","فَلِمُبْتَهِجٍ وَلِمُنْتَهِجِ"],["فَهِجِ الْأَعْمَالَ إِذَا رَكَدَتْ","فَإِذَا مَا هِجْتَ إِذًا تَهِجِ"],["وَمَعَاصِي اللَّهِ سَمَاجَتُهَا","تَزْدَانُ لِذِي الْخُلُقِ السَّمِجِ"],["وَلِطَاعَتِهِ وَصَبَاحَتِهَا","أَنْوَارُ صَبَاحٍ مُنْبَلِجِ"],["مَنْ يَخْطُبْ حُورَ الْخُلْدِ بِهَا","يَظْفَرْ بِالْحُورِ وَبِالْغُنُجِ"],["فَكُنِ الْمَرْضِيَّ لَهَا بِتُقًى","تَرْضَاهُ غَدًا وَتَكُونُ نَجِي"],["وَاتْلُ الْقُرْآنَ بِقَلْبٍ ذِي","حَزَنٍ وَبِصَوْتٍ فِيهِ شَجِي"],["وَصَلَاةُ اللَّيْلِ مَسَافَتُهَا","فَاذْهَبْ فِيهَا بِالْفَهْمِ وَجِي"],["وَتَأَمَّلْهَا وَمَعَانِيهَا","تَأْتِ الْفِرْدَوْسَ وَتَنْفَرِجِ"],["وَاشْرَبْ تَسْنِيمَ مُفَجَّرِهَا","لَا مُمْتَزِجًا وَبِمُمْتَزِجِ"],["مُدِحَ الْعَقْلُ الْآتِيهِ هُدًى","وَهَوًى مُتَوَلٍّ عَنْهُ هُجِي"],["وَكِتَابُ اللَّهِ رِيَاضَتُهُ","لِعُقُولِ الْخَلْقِ بِمُنْدَرِجِ"],["وَخِيَارُ الْخَلْقِ هُدَاتُهُمُ","وَسِوَاهُمْ مِنْ هَمَجِ الْهَمَجِ"],["وَإِذَا كُنْتَ الْمِقْدَامَ فَلَا","تَجْزَعْ فِي الْحَرْبِ مِنَ الرَّهَجِ"],["وَإِذَا أَبْصَرْتَ مَنَارَ هُدًى","فَاظْهَرْ فَرْدًا فَوْقَ الثَّبَجِ"],["وَإِذَا اشْتَاقَتْ نَفْسٌ وَجَدَتْ","أَلَمًا بِالشَّوْقِ الْمُعْتَلِجِ"],["وَثَنَايَا الْحَسْنَا ضَاحِكَةٌ","وَتَمَامُ الضِّحْكِ عَلَى الْفَلَجِ"],["وَعِيَابُ الْأَسْرَارِ اجْتَمَعَتْ","بِأَمَانَتِهَا تَحْتَ الشَّرَجِ"],["وَالرِّفْقُ يَدُومُ لِصَاحِبِهِ","وَالْخَرْقُ يَصِيرُ إِلَى الْهَرَجِ"],["صَلَوَاتُ اللَّهِ عَلَى الْمَهْدِيِّ","الْهَادِي النَّاسِ إِلَى النَّهَجِ"],["وَأَبِي بَكْرٍ فِي سِيرَتِهِ","وَلِسَانِ مَقَالَتِهِ اللَّهِجِ"],["وَأَبِي حَفْصٍ وَكَرَامَتِهِ","فِي قِصَّةِ سَارِيَةَ الْخُلُجِ"],["وَأَبِي عَمْرٍو ذِي النُّورَيْنِ","الْمُسْتَحْيِي الْمُسْتَحْيَا الْبَهِجِ"],["وَأَبِي حَسَنٍ فِي الْعِلْمِ إِذَا","وَافَى بِسَحَائِبِهِ الْخُلُجِ"]],"secs":{"1":"المنفرجة"}}],"sharh":false};
